repo.parcels.py:
"""Parcel records."""


class Parcel:
    def __init__(self, depot, grams):
        self.depot = depot
        self.grams = grams

    def __repr__(self):
        return "Parcel(%r, %r)" % (self.depot, self.grams)


ROWS = [('york', 29), ('leeds', 12), ('leeds', 23), ('leeds', 19), ('york', 58), ('bath', 20), ('bath', 5)]


def load_parcels():
    """Yield the stored parcels one at a time."""
    for depot, grams in ROWS:
        yield Parcel(depot, grams)

repo.ranges.py:
"""Position windows over parcels."""


def grams_between(parcels, low, high):
    """Return the grams of the parcels at positions low to high, both included. Positions start at 1."""
    return [x.grams for x in parcels[low - 1:high - 1]]


def first_gramss(parcels, n):
    """Return the grams of the first n parcels."""
    return grams_between(parcels, 1, n)

